static char*initials(const char*name){if(!name)return g_strdup("");gunichar first=0,last=0;gboolean segment=FALSE;for(const char*p=name;*p;p=g_utf8_next_char(p)){gunichar c=g_utf8_get_char(p);if(g_unichar_isspace(c)){segment=FALSE;continue;}if(!segment){if(!first)first=c;last=c;segment=TRUE;}}char out[13]={0};char*q=out;if(first)q+=g_unichar_to_utf8(g_unichar_toupper(first),q);if(last&&last!=first)q+=g_unichar_to_utf8(g_unichar_toupper(last),q);*q='\0';return g_strdup(out);}
