void bm_avatar_set_src(BmAvatar*s,const char*src){g_return_if_fail(BM_IS_AVATAR(s));if(g_strcmp0(s->src,src)==0)return;g_free(s->src);s->src=g_strdup(src);gboolean loaded=FALSE;if(src&&*src){g_autoptr(GError)e=NULL;g_autoptr(GFile)file=g_file_new_for_commandline_arg(src);GdkTexture*t=gdk_texture_new_from_file(file,&e);if(t){gtk_picture_set_paintable(s->picture,GDK_PAINTABLE(t));g_object_unref(t);loaded=TRUE;}else g_signal_emit(s,signals[SIGNAL_IMAGE_ERROR],0,src);}if(!loaded)gtk_picture_set_paintable(s->picture,NULL);gtk_widget_set_visible(GTK_WIDGET(s->picture),loaded);gtk_widget_set_visible(GTK_WIDGET(s->fallback_widget),!loaded);g_object_notify_by_pspec(G_OBJECT(s),properties[PROP_SRC]);}
