static void dispose(GObject*o){BmAvatar*s=BM_AVATAR(o);if(s->scope&&s->theme_id)g_signal_handler_disconnect(s->scope,s->theme_id);g_clear_object(&s->scope);G_OBJECT_CLASS(bm_avatar_parent_class)->dispose(o);}static void finalize(GObject*o){BmAvatar*s=BM_AVATAR(o);g_free(s->name);g_free(s->label);g_free(s->src);g_free(s->fallback);g_free(s->availability_label);g_free(s->custom_class);G_OBJECT_CLASS(bm_avatar_parent_class)->finalize(o);}
static void bm_avatar_class_init(BmAvatarClass*k){GObjectClass*c=G_OBJECT_CLASS(k);c->get_property=get_prop;c->set_property=set_prop;c->dispose=dispose;c->finalize=finalize;gtk_widget_class_set_accessible_role(GTK_WIDGET_CLASS(k),GTK_ACCESSIBLE_ROLE_IMG);properties[PROP_NAME]=g_param_spec_string("name",NULL,NULL,NULL,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_LABEL]=g_param_spec_string("label",NULL,NULL,NULL,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_SRC]=g_param_spec_string("src",NULL,NULL,NULL,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_KIND]=g_param_spec_enum("kind",NULL,NULL,BM_TYPE_AVATAR_KIND,BM_AVATAR_PERSON,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_SIZE]=g_param_spec_enum("size",NULL,NULL,BM_TYPE_AVATAR_SIZE,BM_AVATAR_MEDIUM,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_AVAILABILITY]=g_param_spec_enum("availability",NULL,NULL,BM_TYPE_AVATAR_AVAILABILITY,BM_AVATAR_AVAILABILITY_NONE,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_AVAILABILITY_LABEL]=g_param_spec_string("availability-label",NULL,NULL,NULL,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);properties[PROP_THEME_SCOPE]=g_param_spec_object("theme-scope",NULL,NULL,BM_TYPE_THEME_SCOPE,G_PARAM_READWRITE|G_PARAM_EXPLICIT_NOTIFY|G_PARAM_STATIC_STRINGS);g_object_class_install_properties(c,N_PROPERTIES,properties);signals[SIGNAL_IMAGE_ERROR]=g_signal_new("image-error",G_TYPE_FROM_CLASS(k),G_SIGNAL_RUN_LAST,0,NULL,NULL,NULL,G_TYPE_NONE,1,G_TYPE_STRING);}
static void bm_avatar_init(BmAvatar*s){gtk_widget_add_css_class(GTK_WIDGET(s),"bm-avatar");s->overlay=GTK_OVERLAY(gtk_overlay_new());s->fallback_widget=GTK_LABEL(gtk_label_new(""));s->picture=GTK_PICTURE(gtk_picture_new());gtk_picture_set_content_fit(s->picture,GTK_CONTENT_FIT_COVER);gtk_overlay_set_child(s->overlay,GTK_WIDGET(s->fallback_widget));gtk_overlay_add_overlay(s->overlay,GTK_WIDGET(s->picture));s->dot=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,0);gtk_widget_add_css_class(s->dot,"bm-avatar-availability");gtk_widget_set_halign(s->dot,GTK_ALIGN_END);gtk_widget_set_valign(s->dot,GTK_ALIGN_END);gtk_overlay_add_overlay(s->overlay,s->dot);gtk_box_append(GTK_BOX(s),GTK_WIDGET(s->overlay));s->size=BM_AVATAR_MEDIUM;update_size(s);update_availability(s);}
